// Function to standardize column names
function cleanName(name) {
  return name
    .replace(/\(.*?\)/g, "")          // Remove text inside brackets
    .replace(/[\/%°]/g, "")           // Remove / % °
    .replace(/-/g, "_")               // Replace - with _
    .replace(/\s+/g, "_")             // Replace spaces with _
    .replace(/[^a-zA-Z0-9_]/g, "")    // Keep only letters, numbers and _
    .replace(/_+/g, "_")              // Replace multiple _ with single _
    .replace(/^_+|_+$/g, "");         // Remove leading/trailing _
}

const items = $input.all();

const output = items.map(item => {

  const newJson = {};

  for (const key of Object.keys(item.json)) {

    const newKey = cleanName(key);

    newJson[newKey] = item.json[key];

  }

  return {
    json: newJson
  };

});

return output;

const numericColumns = [
"Wind_Speed",
"Energy_Budget_default",
"Power",
"Potential_Power",
"Nacelle_Temp",
"Transformer_Temp",
"Gear_Oil_Temp",
"Transformer_Cell_Temp",
"Grid_Voltage",
"Rotor_RPM",
"Generator_RPM",
"Capacity_Factor",
"Blade_Pitch",
"Yaw_Angle",
"Grid_Frequency",
"Performance_Index",
"Drive_Train_Acceleration",
"Tower_Acc_X",
"Tower_Acc_Y"
];

const items = $input.all();

for (const item of items) {

    numericColumns.forEach(col => {

        if (item.json[col] !== "" &&
            item.json[col] !== null &&
            item.json[col] !== undefined) {

            item.json[col] = Number(item.json[col]);

        }

    });

}

return items;

const items = $input.all();

for (const item of items) {

    const missing = [];

    // Check every column
    for (const key in item.json) {

        const value = item.json[key];

        if (
            value === null ||
            value === undefined ||
            value === ""
        ) {
            missing.push(key);
        }
    }

    // Number of missing columns
    item.json.Missing_Count = missing.length;

    // Which columns are missing
    if (missing.length === 0) {
        item.json.Missing_Columns = "None";
        item.json.Data_Status = "Valid";
    } else {
        item.json.Missing_Columns = missing.join(", ");
        item.json.Data_Status = "Invalid";
    }

}

return items;

const items = $input.all();

const seen = new Set();

for (const item of items) {

    // Convert the entire row into text
    const rowString = JSON.stringify(item.json);

    if (seen.has(rowString)) {
        item.json.Duplicate_Status = "Duplicate";
    } else {
        seen.add(rowString);
        item.json.Duplicate_Status = "Original";
    }

}

return items;

const items = $input.all();

// Total records
const totalRecords = items.length;

// Records having missing values
const missingRecords = items.filter(
    item => item.json.Missing_Count > 0
).length;

// Duplicate records
const duplicateRecords = items.filter(
    item => item.json.Duplicate_Status === "Duplicate"
).length;

// Records having impossible values
const impossibleRecords = items.filter(
    item => item.json.Impossible_Value_Count > 0
).length;

// Valid records
const validRecords = items.filter(item =>
    item.json.Data_Status === "Valid" &&
    item.json.Validation_Status === "Valid" &&
    item.json.Duplicate_Status === "Original"
).length;

// Invalid records
const invalidRecords = totalRecords - validRecords;

// Data Quality Score
const qualityScore = (
    (validRecords / totalRecords) * 100
).toFixed(2);

// Return only one summary row
return [
  {
    json: {
      Total_Records: totalRecords,
      Valid_Records: validRecords,
      Invalid_Records: invalidRecords,
      Records_With_Missing_Values: missingRecords,
      Duplicate_Records: duplicateRecords,
      Impossible_Value_Records: impossibleRecords,
      Data_Quality_Score: qualityScore + "%"
    }
  }
];
